     2| * IVX Production Agent Registry — honest runtime registry for the 12 agents.
     3| *
     4| * Replaces the old static-tool-list scoring with a registry that tracks
     5| * REAL runtime state: heartbeat, current job, completed jobs, failures,
     6| * queue depth, concurrency, and owner controls.
     7| *
     8| * HONESTY RULES:
     9| *   - An agent is only VERIFIED if it has runtime evidence, not static config.
    10| *   - Shared workers are labeled SHARED WORKER, never independent agent.
    11| *   - The dashboard MUST read from this registry, not from static card data.
    12| */
    13|import { appendFile, mkdir, readFile, rename, writeFile } from 'node:fs/promises';
    14|import path from 'node:path';
    15|import { randomUUID } from 'node:crypto';
    16|import {
    17|  isDurableStoreConfigured,
    18|  readDurableJson,
    19|  writeDurableJson,
    20|  appendDurableEvent,
    21|} from './ivx-durable-store';
    22|
    23|export const IVX_AGENT_REGISTRY_MARKER = 'ivx-agent-registry-2026-07-25';
    24|
    25|// ── Types ────────────────────────────────────────────────────────────────────
    26|
    27|/**
    28| * Honest classification of an agent's real architecture.
    29| * - REAL_INDEPENDENT_AGENT: Has its own runtime process, isolated state, heartbeat
    30| * - SHARED_WORKER_WITH_ROLE: Runs on a shared worker pool with role-based routing
    31| * - UI_ONLY_LABEL: Exists only in UI/dashboard config, no runtime backing
    32| * - PLACEHOLDER: Stub with no implementation
    33| * - MOCK: Returns fake/canned data
    34| * - BROKEN: Runtime exists but crashes or fails to start
    35| * - UNKNOWN: Not yet classified
    36| */
    37|export type AgentClassification =
    38|  | 'REAL_INDEPENDENT_AGENT'
    39|  | 'SHARED_WORKER_WITH_ROLE'
    40|  | 'UI_ONLY_LABEL'
    41|  | 'PLACEHOLDER'
    42|  | 'MOCK'
    43|  | 'BROKEN'
    44|  | 'UNKNOWN';
    45|
    46|export type AgentStatus =
    47|  | 'online'
    48|  | 'offline'
    49|  | 'degraded'
    50|  | 'crashed'
    51|  | 'never_started'
    52|  | 'disabled';
    53|
    54|export type AgentRuntimeType =
    55|  | 'process'          // own OS process
    56|  | 'shared_worker'    // runs inside a shared worker pool
    57|  | 'in_memory'        // runs inside the main Node process
    58|  | 'config_only';     // no runtime — static config only
    59|
    60|export type AgentCapability = {
    61|  name: string;
    62|  required: boolean;
    63|  verified: boolean;
    64|  evidence: string;
    65|};
    66|
    67|export type AgentRegistryRecord = {
    68|  // ── Identity ──
    69|  agent_id: string;
    70|  agent_name: string;
    71|  role: string;
    72|
    73|  // ── Runtime ──
    74|  runtime_id: string;
    75|  worker_id: string;
    76|  runtime_type: AgentRuntimeType;
    77|  model: string;
    78|
    79|  // ── Classification ──
    80|  classification: AgentClassification;
    81|  shared_worker_pool: string | null;
    82|
    83|  // ── Status ──
    84|  status: AgentStatus;
    85|  heartbeat: string | null;
    86|  current_job: string | null;
    87|  last_completed_job: string | null;
    88|  last_failed_job: string | null;
    89|
    90|  // ── Load ──
    91|  queue_depth: number;
    92|  concurrency_limit: number;
    93|  active_jobs: number;
    94|
    95|  // ── Owner controls ──
    96|  owner_enabled: boolean;
    97|  approval_level: number;
    98|  credentials_required: string[];
    99|  allowed_repositories: string[];
   100|  allowed_environments: string[];
   101|  approval_requirements: string[];
   102|
   103|  // ── Capabilities ──
   104|  capabilities: AgentCapability[];
   105|  prohibited_capabilities: string[];
   106|
   107|  // ── Limits ──
   108|  max_duration_ms: number;
   109|  retry_limit: number;
   110|  cost_limit_usd: number | null;
   111|
   112|  // ── Timestamps ──
   113|  created_at: string;
   114|  updated_at: string;
   115|};
   116|
   117|// ── Registry Storage ─────────────────────────────────────────────────────────
   118|
   119|const REGISTRY_DIR = path.join(process.cwd(), 'logs', 'audit', 'agent-registry');
   120|const REGISTRY_PATH = path.join(REGISTRY_DIR, 'registry.json');
   121|const REGISTRY_LOG_PATH = path.join(REGISTRY_DIR, 'events.jsonl');
   122|
   123|let inMemoryRegistry: Map<string, AgentRegistryRecord> | null = null;
   124|
   125|/**
   126| * Load the registry from durable storage (or in-memory cache).
   127| */
   128|export async function loadAgentRegistry(): Promise<Map<string, AgentRegistryRecord>> {
   129|  if (inMemoryRegistry) return inMemoryRegistry;
   130|
   131|  const registry = new Map<string, AgentRegistryRecord>();
   132|
   133|  try {
   134|    let raw: string;
   135|    if (isDurableStoreConfigured()) {
   136|      const data = await readDurableJson<AgentRegistryRecord[]>(REGISTRY_PATH, []);
   137|      raw = JSON.stringify(data);
   138|    } else {
   139|      raw = await readFile(REGISTRY_PATH, 'utf8');
   140|    }
   141|    const records: AgentRegistryRecord[] = JSON.parse(raw);
   142|    for (const record of records) {
   143|      if (record && typeof record.agent_id === 'string') {
   144|        registry.set(record.agent_id, record);
   145|      }
   146|    }
   147|  } catch {
   148|    // File doesn't exist yet — start with empty registry
   149|  }
   150|
   151|  inMemoryRegistry = registry;
   152|  return registry;
   153|}
   154|
   155|/**
   156| * Persist the registry to durable storage.
   157| */
   158|async function persistAgentRegistry(registry: Map<string, AgentRegistryRecord>): Promise<void> {
   159|  const records = Array.from(registry.values());
   160|
   161|  if (isDurableStoreConfigured()) {
   162|    await writeDurableJson(REGISTRY_PATH, records);
   163|  } else {
   164|    await mkdir(REGISTRY_DIR, { recursive: true });
   165|    const tmp = path.join(REGISTRY_DIR, 'registry.json.tmp');
   166|    await writeFile(tmp, JSON.stringify(records, null, 2), 'utf8');
   167|    await rename(tmp, REGISTRY_PATH);
   168|  }
   169|}
   170|
   171|/**
   172| * Append a registry event to the append-only log.
   173| */
   174|async function appendRegistryEvent(event: Record<string, unknown>): Promise<void> {
   175|  try {
   176|    const entry = JSON.stringify({ ...event, at: new Date().toISOString() });
   177|    if (isDurableStoreConfigured()) {
   178|      await appendDurableEvent(REGISTRY_LOG_PATH, event);
   179|    } else {
   180|      await mkdir(REGISTRY_DIR, { recursive: true });
   181|      await appendFile(REGISTRY_LOG_PATH, `${entry}\n`, 'utf8');
   182|    }
   183|  } catch {
   184|    // best-effort
   185|  }
   186|}
   187|
   188|// ── Registry Operations ──────────────────────────────────────────────────────
   189|
   190|/**
   191| * Get a single agent record by ID.
   192| */
   193|export async function getAgentRecord(agentId: string): Promise<AgentRegistryRecord | null> {
   194|  const registry = await loadAgentRegistry();
   195|  return registry.get(agentId) ?? null;
   196|}
   197|
   198|/**
   199| * Get all agent records.
   200| */
   201|export async function listAgentRecords(): Promise<AgentRegistryRecord[]> {
   202|  const registry = await loadAgentRegistry();
   203|  return Array.from(registry.values()).sort((a, b) => a.agent_id.localeCompare(b.agent_id));
   204|}
   205|
   206|/**
   207| * Update a single agent record. Returns the updated record or null if not found.
   208| */
   209|export async function updateAgentRecord(
   210|  agentId: string,
   211|  updates: Partial<AgentRegistryRecord>,
   212|): Promise<AgentRegistryRecord | null> {
   213|  const registry = await loadAgentRegistry();
   214|  const existing = registry.get(agentId);
   215|  if (!existing) return null;
   216|
   217|  const updated: AgentRegistryRecord = {
   218|    ...existing,
   219|    ...updates,
   220|    agent_id: existing.agent_id, // immutable
   221|    updated_at: new Date().toISOString(),
   222|  };
   223|
   224|  registry.set(agentId, updated);
   225|  await persistAgentRegistry(registry);
   226|  await appendRegistryEvent({
   227|    type: 'record_updated',
   228|    agent_id: agentId,
   229|    fields: Object.keys(updates),
   230|  });
   231|
   232|  return updated;
   233|}
   234|
   235|/**
   236| * Record a heartbeat for an agent.
   237| */
   238|export async function recordAgentHeartbeat(agentId: string): Promise<AgentRegistryRecord | null> {
   239|  return updateAgentRecord(agentId, {
   240|    heartbeat: new Date().toISOString(),
   241|    status: 'online',
   242|  });
   243|}
   244|
   245|/**
   246| * Record a job completion for an agent.
   247| */
   248|export async function recordJobCompleted(
   249|  agentId: string,
   250|  jobId: string,
   251|): Promise<AgentRegistryRecord | null> {
   252|  const record = await getAgentRecord(agentId);
   253|  if (!record) return null;
   254|
   255|  return updateAgentRecord(agentId, {
   256|    last_completed_job: jobId,
   257|    current_job: null,
   258|    active_jobs: Math.max(0, record.active_jobs - 1),
   259|    queue_depth: Math.max(0, record.queue_depth - 1),
   260|  });
   261|}
   262|
   263|/**
   264| * Record a job failure for an agent.
   265| */
   266|export async function recordJobFailed(
   267|  agentId: string,
   268|  jobId: string,
   269|): Promise<AgentRegistryRecord | null> {
   270|  const record = await getAgentRecord(agentId);
   271|  if (!record) return null;
   272|
   273|  return updateAgentRecord(agentId, {
   274|    last_failed_job: jobId,
   275|    current_job: null,
   276|    active_jobs: Math.max(0, record.active_jobs - 1),
   277|  });
   278|}
   279|
   280|/**
   281| * Assign a job to an agent.
   282| */
   283|export async function assignJobToAgent(
   284|  agentId: string,
   285|  jobId: string,
   286|): Promise<AgentRegistryRecord | null> {
   287|  const record = await getAgentRecord(agentId);
   288|  if (!record) return null;
   289|
   290|  if (record.active_jobs >= record.concurrency_limit) {
   291|    return updateAgentRecord(agentId, {
   292|      queue_depth: record.queue_depth + 1,
   293|    });
   294|  }
   295|
